import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { Route as ForgotPasswordRoute } from "./forgot-password";
import { Route as ResetPasswordRoute } from "./reset-password";
import { Route as VerifyEmailRoute } from "./verify-email";

/**
 * The three screens the transactional emails point at.
 *
 * Every one of these links is generated by the backend and lands cold: the
 * customer clicked it from an inbox, possibly in a different browser, and the
 * route is the first thing that runs. If any of them is missing or mis-parses
 * its token, an account that has already been paid for cannot be verified,
 * recovered, or used to publish — so the contract is asserted directly.
 *
 * The token schema is asserted rather than the rendered screen: it is a pure
 * function, and the interesting cases are the malformed ones an email client
 * or a URL shortener can produce.
 */
type Schema =
  | ((s: Record<string, unknown>) => Record<string, unknown>)
  | { parse: (s: Record<string, unknown>) => Record<string, unknown> };

function validator(route: { options: { validateSearch?: unknown } }) {
  const schema = route.options.validateSearch as Schema;
  return (search: Record<string, unknown>): Record<string, unknown> =>
    typeof schema === "function" ? schema(search) : schema.parse(search);
}

describe.each([
  ["verify-email", VerifyEmailRoute],
  ["reset-password", ResetPasswordRoute],
])("%s token", (_name, route) => {
  const validate = validator(route);

  it("keeps a token from the emailed link", () => {
    expect(validate({ token: "abc.def.ghi" }).token).toBe("abc.def.ghi");
  });

  it("is absent when the link was truncated", () => {
    // The screen has to distinguish "no token" from "bad token": one asks the
    // customer to reopen the email, the other to request a fresh link.
    expect(validate({}).token).toBeUndefined();
    expect(validate({ token: "" }).token).toBeUndefined();
  });

  it("drops a non-string token instead of throwing", () => {
    expect(validate({ token: 42 }).token).toBeUndefined();
    expect(validate({ token: null }).token).toBeUndefined();
  });

  it("drops an oversized token rather than sending it upstream", () => {
    expect(validate({ token: "x".repeat(600) }).token).toBeUndefined();
  });
});

describe("account recovery routes", () => {
  it.each([
    [VerifyEmailRoute, "Confirm your email · Magnitai"],
    [ForgotPasswordRoute, "Reset your password · Magnitai"],
    [ResetPasswordRoute, "Set a new password · Magnitai"],
  ])("titles its page", (route, title) => {
    const head = route.options.head as () => { meta: Array<{ title: string }> };
    expect(head().meta[0].title).toBe(title);
  });

  it("has a route file for every path the backend emails", () => {
    // The two halves of this link live in different languages and different
    // deployments, so nothing else fails when they disagree — the customer just
    // gets a 404 in their inbox and the account stays unusable. Reading the
    // Python source is blunt on purpose: it is the only place both sides meet.
    // Resolved from the project root: under jsdom, import.meta.url is an http
    // URL rather than a file one.
    const templates = readFileSync(
      resolve(process.cwd(), "../magai-be/app/platform/email/templates.py"),
      "utf8",
    );
    const emailed = [...templates.matchAll(/_link\(\s*"(\/[^"]+)"/g)].map((match) => match[1]);

    expect(emailed).toContain("/verify-email");
    expect(emailed).toContain("/reset-password");

    const routesDir = resolve(process.cwd(), "src/routes");
    for (const path of emailed) {
      expect(
        existsSync(join(routesDir, `${path}.tsx`)),
        `${path} is emailed to customers but has no route file`,
      ).toBe(true);
    }
  });
});
